(()=>{function b(a){return new Promise(c=>setTimeout(c,a))}(()=>{document.querySelectorAll(".linkBox").forEach(a=>{a.addEventListener("mouseover",()=>{a.classList.add("boxShadow")})});document.querySelectorAll(".linkBox").forEach(a=>{a.addEventListener("mouseleave",()=>{a.classList.remove("boxShadow")})});document.getElementById("githubicon").addEventListener("mouseover",()=>{document.getElementById("githubicon").classList.add("upBounce");document.getElementById("githubicon").classList.remove("downBounce")});
document.getElementById("githubicon").addEventListener("mouseleave",()=>{document.getElementById("githubicon").classList.add("downBounce");document.getElementById("githubicon").classList.remove("upBounce");b(1E3).then(()=>document.getElementById("githubicon").classList.remove("downBounce"))})})()})();
